// C294 B3: decomposition-independent recursive separator normal form.
//
// For every high-cycle residual, enumerate every bounded two-port separator
// piece used by the checked live probes.  Intern every single-piece abstraction
// and every prefix of the intrinsic recursive parallel composition, then take
// the equivalence closure generated by equal complete context/interface keys.
// The least key in each resulting component is a normal form independent of
// separator choice, previously seen transition classes, and cache history.
#define C294_TWO_PORT_LIVE_NO_MAIN
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"
#include "2026-07-17-c294-b3-two-port-live.cpp"
#pragma GCC diagnostic pop
#undef C294_TWO_PORT_LIVE_NO_MAIN

class RecursiveSeparatorProbe : public TwoPortLiveProbe {
  public:
    struct Entry {
        uint8_t value = 0;
        Mask representative;
        std::vector<int> absolute_key;
        std::vector<Candidate> pieces;
    };

    struct Representation {
        size_t class_id = 0;
        Entry entry;
    };

    RecursiveSeparatorProbe(size_t game_limit, size_t interface_limit)
        : TwoPortLiveProbe(game_limit, interface_limit) {}

    uint8_t nimber(Mask mask) {
        if (empty(mask)) return 0;
        std::vector<Mask> parts = components(mask);
        if (parts.size() != 1) {
            ++decompositions;
            uint8_t value = 0;
            for (Mask part : parts) value ^= nimber(part);
            return value;
        }

        int vertices = size(mask);
        int twice_edges = 0;
        int maximum_degree = 0;
        Mask scan = mask;
        while (!empty(scan)) {
            int vertex = pop_first(scan);
            int degree = size(adjacency[vertex] & mask);
            twice_edges += degree;
            maximum_degree = std::max(maximum_degree, degree);
        }
        int edges = twice_edges / 2;
        if (maximum_degree <= 2) {
            ++path_cycle_hits;
            if (edges == vertices - 1) return path_nimber_[vertices];
            if (edges == vertices && vertices >= 3) return cycle_nimber_[vertices];
            throw std::runtime_error("unexpected connected maximum-degree-two graph");
        }
        if (edges == vertices - 1) {
            std::string key = tree_key(mask);
            auto found = tree_cache_.find(key);
            if (found != tree_cache_.end()) {
                ++tree_cache_hits;
                return found->second;
            }
            uint8_t value = evaluate_connected_normal(mask);
            tree_cache_.emplace(std::move(key), value);
            ++tree_shapes;
            return value;
        }
        if (edges == vertices) {
            std::string key = unicyclic_key(mask);
            auto found = unicyclic_cache_.find(key);
            if (found != unicyclic_cache_.end()) {
                ++unicyclic_cache_hits;
                return found->second;
            }
            uint8_t value = evaluate_connected_normal(mask);
            unicyclic_cache_.emplace(std::move(key), value);
            ++unicyclic_shapes;
            return value;
        }

        int cyclomatic = edges - vertices + 1;
        std::vector<int> absolute_key;
        if (cyclomatic >= 2 && cyclomatic <= 4) {
            absolute_key = low_cyclomatic_keys(mask, cyclomatic).candidate;
            ++low_key_requests;
        } else {
            absolute_key = sparse_absolute_core_key(mask, cyclomatic);
            ++high_key_requests;
        }

        auto found = quotient_cache_.find(absolute_key);
        if (found != quotient_cache_.end()) {
            ++quotient_cache_hits;
            return found->second.value;
        }

        uint8_t value = evaluate_connected_normal(mask);
        std::vector<Candidate> candidates;
        std::vector<Candidate> recursive;
        if (cyclomatic >= 5 && !interface_disabled_) {
            try {
                candidates = enumerate_candidates(mask);
                recursive = normal_form(mask, candidates);
            } catch (const InterfaceLimitReached &) {
                interface_stopped_ = true;
                interface_disabled_ = true;
                candidates.clear();
                recursive.clear();
            }
        }
        Entry current{value, mask, absolute_key, {}};
        size_t class_id = parent_.size();
        parent_.push_back(class_id);
        rank_.push_back(0);
        class_value_.push_back(value);
        for (const Candidate &candidate : candidates) {
            Entry represented = current;
            represented.pieces = {candidate};
            record_representation(abstract_key(mask, represented.pieces), class_id, represented);
        }
        std::vector<Candidate> prefix;
        for (const Candidate &candidate : recursive) {
            prefix.push_back(candidate);
            if (prefix.size() < 2) continue;
            Entry represented = current;
            represented.pieces = prefix;
            record_representation(abstract_key(mask, represented.pieces), class_id, represented);
        }
        if (!candidates.empty()) ++normal_form_insertions;
        quotient_cache_.emplace(absolute_key, std::move(current));
        if (cyclomatic >= 2 && cyclomatic <= 4) ++low_cyclomatic_shapes;
        return value;
    }

    uint64_t quotient_cache_hits = 0;
    uint64_t normal_form_requests = 0;
    uint64_t normal_form_insertions = 0;
    uint64_t eligible_occurrences = 0;
    uint64_t selected_pieces = 0;
    uint64_t positions_with_multiple_pieces = 0;
    uint64_t nested_competitions = 0;
    uint64_t new_absolute_hits = 0;
    uint64_t cross_exact_hits = 0;
    uint64_t cross_exact_recursive_hits = 0;
    uint64_t value_conflicts = 0;
    uint64_t representations = 0;
    int maximum_selected_pieces = 0;

    size_t quotient_classes() const { return quotient_cache_.size(); }
    size_t normal_form_classes() const {
        size_t result = 0;
        for (size_t index = 0; index < parent_.size(); ++index) {
            if (parent_[index] == index) ++result;
        }
        return result;
    }
    bool interface_stopped() const { return interface_stopped_; }
    bool has_first_cross_exact() const { return has_first_cross_exact_; }
    const Entry &first_prior() const { return first_prior_; }
    const Entry &first_current() const { return first_current_; }

  private:
    uint8_t evaluate_connected_normal(Mask mask) {
        if (connected_states >= limit_) {
            limit_vertices = size(mask);
            throw LimitReached();
        }
        int twice_edges = 0;
        Mask scan = mask;
        while (!empty(scan)) {
            int vertex = pop_first(scan);
            twice_edges += size(adjacency[vertex] & mask);
        }
        int cyclomatic = twice_edges / 2 - size(mask) + 1;
        ++cyclomatic_states[std::min(cyclomatic, 16)];
        ++connected_states;
        std::array<uint64_t, 2> seen{};
        Mask moves = mask;
        while (!empty(moves)) {
            int vertex = pop_first(moves);
            uint8_t child = nimber(and_not(mask, closed[vertex]));
            if (child < 64) seen[0] |= 1ULL << child;
            else seen[1] |= 1ULL << (child - 64);
        }
        if (~seen[0]) return static_cast<uint8_t>(__builtin_ctzll(~seen[0]));
        return static_cast<uint8_t>(64 + __builtin_ctzll(~seen[1]));
    }

    std::vector<Candidate> enumerate_candidates(Mask mask) {
        Mask core = two_core(mask);
        std::vector<int> vertices;
        Mask scan = core;
        while (!empty(scan)) vertices.push_back(pop_first(scan));
        std::vector<Candidate> result;
        for (size_t first = 0; first < vertices.size(); ++first) {
            for (size_t second = first + 1; second < vertices.size(); ++second) {
                int a = vertices[first];
                int b = vertices[second];
                Mask remainder = and_not(and_not(core, singleton(a)), singleton(b));
                std::vector<Mask> parts = components(remainder);
                if (parts.size() < 2) continue;
                for (Mask component : parts) {
                    if (size(component) < 8) continue;
                    if (empty(adjacency[a] & component) ||
                        empty(adjacency[b] & component)) continue;
                    Candidate current;
                    current.piece = expanded_piece(mask, core, component);
                    current.first_port = a;
                    current.second_port = b;
                    current.core_vertices = size(component);
                    current.expanded_vertices = size(current.piece);
                    if (current.expanded_vertices > 16) continue;
                    current.exact_key = piece_key(mask, core, component, a, b);
                    auto ids = transition_->ordered_ids(
                        current.piece, current.first_port, current.second_port
                    );
                    current.forward_id = ids.forward;
                    current.reverse_id = ids.reverse;
                    ++eligible_occurrences;
                    result.push_back(std::move(current));
                }
            }
        }
        return result;
    }

    static bool compatible(const Candidate &candidate,
                           const std::vector<Candidate> &selected) {
        for (const Candidate &prior : selected) {
            if (!empty(candidate.piece & prior.piece)) return false;
            if (!empty(candidate.piece & singleton(prior.first_port)) ||
                !empty(candidate.piece & singleton(prior.second_port))) return false;
            if (!empty(prior.piece & singleton(candidate.first_port)) ||
                !empty(prior.piece & singleton(candidate.second_port))) return false;
        }
        return true;
    }

    std::vector<int> oriented_key(Mask mask,
                                  const std::vector<Candidate> &pieces,
                                  unsigned orientation) {
        Mask removed{};
        for (const Candidate &piece : pieces) removed = removed | piece.piece;
        Mask context = and_not(mask, removed);
        std::vector<int> vertices;
        std::array<int, 128> local{};
        local.fill(-1);
        Mask scan = context;
        while (!empty(scan)) {
            int vertex = pop_first(scan);
            local[vertex] = static_cast<int>(vertices.size());
            vertices.push_back(vertex);
        }
        size_t actual = vertices.size();
        std::vector<std::vector<int>> neighbours(actual + 2 * pieces.size());
        std::vector<int> labels(actual + 2 * pieces.size(), 0);
        for (size_t index = 0; index < actual; ++index) {
            Mask adjacent = adjacency[vertices[index]] & context;
            while (!empty(adjacent)) neighbours[index].push_back(local[pop_first(adjacent)]);
        }
        for (size_t index = 0; index < pieces.size(); ++index) {
            const Candidate &piece = pieces[index];
            bool reverse = (orientation & (1U << index)) != 0;
            int identifier = reverse ? piece.reverse_id : piece.forward_id;
            int first_port = reverse ? piece.second_port : piece.first_port;
            int second_port = reverse ? piece.first_port : piece.second_port;
            if (local[first_port] < 0 || local[second_port] < 0) {
                throw std::runtime_error("normal-form port removed by another piece");
            }
            int first_marker = static_cast<int>(actual + 2 * index);
            int second_marker = first_marker + 1;
            labels[first_marker] = 1 + 2 * identifier;
            labels[second_marker] = 2 + 2 * identifier;
            neighbours[first_marker] = {local[first_port], second_marker};
            neighbours[second_marker] = {local[second_port], first_marker};
            neighbours[local[first_port]].push_back(first_marker);
            neighbours[local[second_port]].push_back(second_marker);
        }
        for (auto &list : neighbours) std::sort(list.begin(), list.end());
        return canonical_graph_key(-5, neighbours, labels);
    }

    std::vector<int> abstract_key(Mask mask,
                                  const std::vector<Candidate> &pieces) {
        if (pieces.size() >= 31) {
            throw std::runtime_error("too many simultaneous separator pieces");
        }
        std::vector<int> result;
        unsigned orientations = 1U << pieces.size();
        for (unsigned orientation = 0; orientation < orientations; ++orientation) {
            std::vector<int> candidate = oriented_key(mask, pieces, orientation);
            if (result.empty() || candidate < result) result = std::move(candidate);
        }
        result.insert(result.begin(), std::numeric_limits<int>::min() + 3);
        return result;
    }

    std::vector<Candidate> normal_form(
        Mask mask, const std::vector<Candidate> &candidates
    ) {
        ++normal_form_requests;
        std::vector<Candidate> selected;
        std::vector<bool> used(candidates.size(), false);
        while (true) {
            size_t best = candidates.size();
            std::vector<int> best_key;
            std::vector<int> best_exact;
            int competing = 0;
            for (size_t index = 0; index < candidates.size(); ++index) {
                if (used[index] || !compatible(candidates[index], selected)) continue;
                ++competing;
                std::vector<Candidate> trial = selected;
                trial.push_back(candidates[index]);
                std::vector<int> key = abstract_key(mask, trial);
                if (best == candidates.size() || key < best_key ||
                    (key == best_key && candidates[index].exact_key < best_exact)) {
                    best = index;
                    best_key = std::move(key);
                    best_exact = candidates[index].exact_key;
                }
            }
            if (best == candidates.size()) break;
            if (selected.empty() && competing > 1) ++nested_competitions;
            selected.push_back(candidates[best]);
            used[best] = true;
        }
        selected_pieces += selected.size();
        if (selected.size() > 1) ++positions_with_multiple_pieces;
        maximum_selected_pieces = std::max(
            maximum_selected_pieces, static_cast<int>(selected.size())
        );
        return selected;
    }

    size_t root(size_t class_id) {
        while (parent_[class_id] != class_id) {
            parent_[class_id] = parent_[parent_[class_id]];
            class_id = parent_[class_id];
        }
        return class_id;
    }

    void unite(size_t first, size_t second) {
        first = root(first);
        second = root(second);
        if (first == second) return;
        if (class_value_[first] != class_value_[second]) ++value_conflicts;
        if (rank_[first] < rank_[second]) std::swap(first, second);
        parent_[second] = first;
        if (rank_[first] == rank_[second]) ++rank_[first];
    }

    void record_representation(
        std::vector<int> key, size_t class_id, const Entry &entry
    ) {
        ++representations;
        auto [where, inserted] = representations_.emplace(
            std::move(key), Representation{class_id, entry}
        );
        if (inserted || where->second.entry.absolute_key == entry.absolute_key) return;
        ++new_absolute_hits;
        unite(where->second.class_id, class_id);
        if (different_realization(where->second.entry.pieces, entry.pieces)) {
            ++cross_exact_hits;
            if (where->second.entry.pieces.size() > 1 || entry.pieces.size() > 1) {
                ++cross_exact_recursive_hits;
            }
            if (!has_first_cross_exact_) {
                has_first_cross_exact_ = true;
                first_prior_ = where->second.entry;
                first_current_ = entry;
            }
        }
    }

    static bool different_realization(const std::vector<Candidate> &a,
                                      const std::vector<Candidate> &b) {
        std::vector<std::vector<int>> a_keys;
        std::vector<std::vector<int>> b_keys;
        for (const Candidate &candidate : a) a_keys.push_back(candidate.exact_key);
        for (const Candidate &candidate : b) b_keys.push_back(candidate.exact_key);
        std::sort(a_keys.begin(), a_keys.end());
        std::sort(b_keys.begin(), b_keys.end());
        return a_keys != b_keys;
    }

    bool interface_stopped_ = false;
    bool interface_disabled_ = false;
    std::unordered_map<std::vector<int>, Entry, VectorHash> quotient_cache_;
    std::unordered_map<std::vector<int>, Representation, VectorHash> representations_;
    std::vector<size_t> parent_;
    std::vector<uint8_t> rank_;
    std::vector<uint8_t> class_value_;
    bool has_first_cross_exact_ = false;
    Entry first_prior_;
    Entry first_current_;
};

static void emit_normal_entry(std::ostream &output,
                              const RecursiveSeparatorProbe::Entry &entry) {
    output << "{\"pieces\": [";
    for (size_t index = 0; index < entry.pieces.size(); ++index) {
        if (index != 0) output << ", ";
        emit_candidate(output, entry.representative, entry.pieces[index]);
    }
    output << "], \"residual\": ";
    emit_mask(output, entry.representative);
    output << "}";
}

int main(int argc, char **argv) {
    if (argc < 3 || argc > 4) {
        std::cerr << "usage: c294-b3-recursive-separator-normal-form "
                     "GAME_STATE_LIMIT INTERFACE_STATE_LIMIT [OUTPUT]\n";
        return 2;
    }
    size_t game_limit = std::strtoull(argv[1], nullptr, 10);
    size_t interface_limit = std::strtoull(argv[2], nullptr, 10);
    int field_order;
    int type_index;
    int graph_size;
    if (!(std::cin >> field_order >> type_index >> graph_size) ||
        graph_size < 0 || graph_size > 128) return 2;
    RecursiveSeparatorProbe solver(game_limit, interface_limit);
    solver.adjacency.resize(graph_size);
    solver.closed.resize(graph_size);
    for (int vertex = 0; vertex < graph_size; ++vertex) {
        std::cin >> solver.adjacency[vertex].lo >> solver.adjacency[vertex].hi;
        solver.closed[vertex] = solver.adjacency[vertex] | singleton(vertex);
    }
    Mask root;
    std::cin >> root.lo >> root.hi;
    solver.initialize_transition();
    bool game_stopped = false;
    int value = -1;
    try {
        value = solver.nimber(root);
    } catch (const LimitReached &) {
        game_stopped = true;
    }

    std::ofstream output_file;
    std::ostream *output = &std::cout;
    if (argc == 4) {
        output_file.open(argv[3]);
        if (!output_file) return 2;
        output = &output_file;
    }
    *output << "{\n"
            << "  \"connected_states\": " << solver.connected_states << ",\n"
            << "  \"cross_exact_hits\": " << solver.cross_exact_hits << ",\n"
            << "  \"cross_exact_recursive_hits\": "
            << solver.cross_exact_recursive_hits << ",\n"
            << "  \"decompositions\": " << solver.decompositions << ",\n"
            << "  \"eligible_occurrences\": " << solver.eligible_occurrences << ",\n"
            << "  \"field_order\": " << field_order << ",\n"
            << "  \"first_cross_exact_hit\": ";
    if (!solver.has_first_cross_exact()) {
        *output << "null";
    } else {
        *output << "{\"current\": ";
        emit_normal_entry(*output, solver.first_current());
        *output << ", \"prior\": ";
        emit_normal_entry(*output, solver.first_prior());
        *output << "}";
    }
    *output << ",\n"
            << "  \"follower_nimber\": " << value << ",\n"
            << "  \"game_state_limit\": " << game_limit << ",\n"
            << "  \"game_stopped_at_limit\": "
            << (game_stopped ? "true" : "false") << ",\n"
            << "  \"high_key_requests\": " << solver.high_key_requests << ",\n"
            << "  \"interface_nodes\": " << solver.interface_nodes() << ",\n"
            << "  \"interface_state_limit\": " << interface_limit << ",\n"
            << "  \"interface_states\": " << solver.interface_states() << ",\n"
            << "  \"interface_stopped_at_limit\": "
            << (solver.interface_stopped() ? "true" : "false") << ",\n"
            << "  \"low_key_requests\": " << solver.low_key_requests << ",\n"
            << "  \"maximum_selected_pieces\": "
            << solver.maximum_selected_pieces << ",\n"
            << "  \"nested_competitions\": " << solver.nested_competitions << ",\n"
            << "  \"new_absolute_hits\": " << solver.new_absolute_hits << ",\n"
            << "  \"normal_form_classes\": " << solver.normal_form_classes() << ",\n"
            << "  \"normal_form_insertions\": "
            << solver.normal_form_insertions << ",\n"
            << "  \"normal_form_requests\": " << solver.normal_form_requests << ",\n"
            << "  \"positions_with_multiple_pieces\": "
            << solver.positions_with_multiple_pieces << ",\n"
            << "  \"quotient_cache_hits\": " << solver.quotient_cache_hits << ",\n"
            << "  \"quotient_classes\": " << solver.quotient_classes() << ",\n"
            << "  \"quotient_class_reduction\": "
            << solver.quotient_classes() - solver.normal_form_classes() << ",\n"
            << "  \"representations\": " << solver.representations << ",\n"
            << "  \"selected_pieces\": " << solver.selected_pieces << ",\n"
            << "  \"selector\": \"fixed-prefix-recursive-separator-congruence-closure\",\n"
            << "  \"type_index\": " << type_index << ",\n"
            << "  \"value_conflicts\": " << solver.value_conflicts << "\n"
            << "}\n";
}
